// Fails when data/dictionary.yaml does not describe every table and column drizzle knows about,
// so personal data can never arrive unmarked. Reads the newest drizzle snapshot (generated by
// `pnpm db:generate`), which is the schema as migrations produce it.
import { readFileSync, readdirSync } from 'node:fs';
import { parse } from 'yaml';

export function gaps(dictionary, snapshot) {
  const out = [];
  for (const table of Object.values(snapshot.tables ?? {})) {
    if (table.schema && table.schema !== 'public' && table.schema !== '') continue;
    const entry = dictionary.tables?.[table.name];
    if (!entry) {
      out.push(table.name);
      continue;
    }
    if (entry.snapshot === 'skip') continue;
    for (const col of Object.values(table.columns ?? {})) {
      if (!entry.columns?.[col.name]) out.push(`${table.name}.${col.name}`);
    }
  }
  for (const [name, t] of Object.entries(dictionary.tables ?? {})) {
    for (const [col, c] of Object.entries(t.columns ?? {})) {
      if (c?.sensitive && !c.pii_kind) out.push(`${name}.${col} is sensitive but has no pii_kind`);
    }
  }
  return out;
}

export function newestSnapshot(dir = 'drizzle/meta') {
  const files = readdirSync(dir)
    .filter((f) => f.endsWith('_snapshot.json'))
    .sort();
  const last = files[files.length - 1];
  if (!last) throw new Error('no drizzle snapshot; run pnpm db:generate');
  return JSON.parse(readFileSync(`${dir}/${last}`, 'utf8'));
}

if (process.argv[1] && import.meta.url.endsWith(process.argv[1].split('/').pop())) {
  const dictionary = parse(readFileSync('data/dictionary.yaml', 'utf8'));
  if (dictionary?.version !== 1) {
    console.error('data/dictionary.yaml must declare version: 1');
    process.exit(1);
  }
  const missing = gaps(dictionary, newestSnapshot());
  if (missing.length) {
    console.error('data/dictionary.yaml does not describe:\n  ' + missing.join('\n  '));
    process.exit(1);
  }
  console.log('dictionary covers every table and column');
}
